//! Writes `guest-sdks/dotnet/native/isoplane_exports.h`, the C declaration of
//! each guest export, from `exports::SIGNATURES`. Each declaration names its
//! export, so a definition is exported under the contract's name and the
//! compiler refuses one whose signature differs.

#![forbid(unsafe_code)]

use std::error::Error;
use std::fmt::Write;

use isoplane_abi::exports::SIGNATURES;
use isoplane_abi::imports::Ty;

fn main() -> Result<(), Box<dyn Error>> {
    let mut text = String::from(
        "/* Generated by `task generate:abi` from isoplane_abi::exports::SIGNATURES. */\n#include <stdint.h>\n",
    );
    for (name, signature) in SIGNATURES {
        let result = match signature.results {
            [] => "void",
            [ty] => scalar(*ty),
            _ => return Err(format!("{name} returns more than one value").into()),
        };
        let parameters = signature
            .params
            .iter()
            .enumerate()
            .map(|(index, ty)| format!("{} a{index}", scalar(*ty)))
            .collect::<Vec<_>>();
        let parameters = if parameters.is_empty() {
            "void".to_owned()
        } else {
            parameters.join(", ")
        };
        writeln!(
            text,
            "__attribute__((export_name(\"{name}\")))\n{result} {name}({parameters});"
        )?;
    }
    std::fs::write(
        concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../guest-sdks/dotnet/native/isoplane_exports.h"
        ),
        text,
    )?;
    Ok(())
}

fn scalar(ty: Ty) -> &'static str {
    match ty {
        Ty::I32 => "int32_t",
        Ty::I64 => "int64_t",
    }
}
